effect.shader:
const float PI = 3.14159265;

float hash(float x) {
    return fract(sin(x * 127.1 + seed * 37.13) * 43758.5453);
}

vec2 girar(vec2 v, float rad) {
    float c = cos(rad);
    float s = sin(rad);
    return vec2(v.x * c - v.y * s, v.x * s + v.y * c);
}

vec4 sobre(vec4 baixo, vec4 cima) {
    float a = cima.a + baixo.a * (1.0 - cima.a);
    if (a <= 0.0) return vec4(0.0);
    return vec4((cima.rgb * cima.a + baixo.rgb * baixo.a * (1.0 - cima.a)) / a, a);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    int quantas = clamp(int(copies + 0.5), 1, 16);
    vec2 meio = vec2(center.x * acAspect, center.y);
    vec2 p = vec2(acScreenNorm.x * acAspect, acScreenNorm.y);

    vec4 montado = vec4(0.0);
    float abertura = arc * PI / 180.0;
    float inicio = startAngle * PI / 180.0;

    // De trás para frente: a cópia 1 acaba por cima, que é a que se lê como "a
    // original" quando elas se cruzam.
    for (int i = 16; i >= 1; i--) {
        if (i > quantas) continue;
        float indice = float(i - 1);

        // Onde esta cópia está.
        vec2 desloca;
        float giro = spin * PI / 180.0 * indice;

        if (mode == 0) {
            // O arco fechado (360°) divide por N; o arco aberto divide por N-1,
            // senão a primeira e a última cópia caem em cima uma da outra.
            float divisor = abertura >= 6.2 ? float(quantas) : max(float(quantas - 1), 1.0);
            float ang = inicio + abertura * indice / divisor;
            desloca = vec2(cos(ang), sin(ang)) * radius;
            if (faceCenter) giro += ang + PI * 0.5;
        } else if (mode == 1) {
            float ang = lineAngle * PI / 180.0;
            desloca = vec2(cos(ang), sin(ang)) * radius * indice;
        } else {
            desloca = vec2(hash(indice * 3.7) - 0.5, hash(indice * 7.1) - 0.5) * radius * 2.0;
            giro += (hash(indice * 11.3) - 0.5) * 2.0 * PI * 0.15;
        }

        float escala = 1.0 + shrink * indice;
        if (abs(escala) < 0.02) continue;

        // A volta: tira o deslocamento, desfaz o giro, desfaz a escala.
        vec2 local = girar(p - meio - desloca, -giro) / escala + meio;
        vec2 uv = vec2(local.x / max(acAspect, 1e-4), local.y);

        // Fora do quadro não há camada — e sem este corte, o CLAMP_TO_EDGE
        // esticaria a borda da imagem por toda a tela.
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) continue;

        vec4 copia = texture(inputImg, uv);
        copia.a *= max(1.0 - fade * indice, 0.0);
        montado = sobre(montado, copia);
    }

    fragColor = keepOriginal ? sobre(montado, original) : montado;
}
